type Service={deliverableItems?:string[];certificationItems?:string[];catalogueReference?:CatalogueReference;missingToolRequirements?:ToolRequirement[];scopeSteps?:string[];missingSkillCodes?:string[];justificationReasons?:string[];justification?:string;specialistRequired?:boolean;skillRequirements?:ResourceSkill[];id:string;categoryCode:string;subcategoryCode:string;classCode:string;catalogCode:string;description:string;attributes:Record<string,string>;proposedVendorIds:string[];scope?:string;deliverables?:string;quantity?:number;qualifications?:string;expectedCost?:number|null;acceptanceCriteria?:string;instructions?:string;certifications?:string;personnel?:number;durationHours?:number;executionDate?:string;supplierCategory?:string;attachments?:string[]};
